; Moves a runner hazard one cell: play_runner_sound (sound $89), draws tile $1C (char E5, the track) at the
; old column runner_old_col and tile $1B (char E4, the runner) at the new column runner_col, both in row
; runner_row. The char $64 of the runner tile kills an actor on contact (handle_touched_tile).
; Used by rooms 7, 9 and 17 and by the room 13 floor movers (update_floor_movers).
draw_runner_step
        jsr play_runner_sound
        lda #$1c                        ; tile $1C (E5) at the old column
        ldx runner_row
        ldy runner_old_col
        jsr print_message
        lda #$1b                        ; tile $1B (E4) at the new column
        ldx runner_row
        ldy runner_col
        jmp print_message
